namespace Celeste.Mods.PrismaticHelper.Rendering.Panels
{
    internal sealed class PanelRoomGroups
    {
        internal sealed class Group
        {
            public string RoomName;
            public readonly List<StylegroundsPanel> Panels = new();
        }

        private readonly Dictionary<RoomKey, int> indices = new();
        private readonly List<Group> groups = new();
        public int Count { get; private set; }

        public Group this[int i] => groups[i];
        public void Clear()
        {
            indices.Clear();
            for (int i = 0; i < Count; i++)
                groups[i].Panels.Clear();
            Count = 0;
        }

        public void Add(string room, StylegroundsPanel panel)
        {
            var key = new RoomKey(room);
            if (!indices.TryGetValue(key, out int index))
            {
                index = Count++;
                if (index == groups.Count)
                    groups.Add(new Group());
                groups[index].RoomName = room;
                indices.Add(key, index);
            }

            if (panel != null)
                groups[index].Panels.Add(panel);
        }

        private readonly struct RoomKey : IEquatable<RoomKey>
        {
            private readonly string room;
            public RoomKey(string room) => this.room = room;
            public bool Equals(RoomKey other) => StringComparer.Ordinal.Equals(room, other.room);
            public override bool Equals(object value) => value is RoomKey other && Equals(other);
            public override int GetHashCode() => room == null ? 0 : StringComparer.Ordinal.GetHashCode(room);
        }
    }
}

